package com.lingdong.learning.organization.onboarding;
import com.lingdong.learning.organization.onboarding.application.OrganizationOnboardingService;
import com.lingdong.learning.organization.onboarding.infrastructure.persistence.OnboardingMapper;
import com.lingdong.learning.organization.infrastructure.persistence.OrganizationMapper;
import com.lingdong.learning.user.infrastructure.persistence.*;
import com.lingdong.learning.user.domain.*;
import com.lingdong.learning.iam.infrastructure.persistence.RoleMapper;
import com.lingdong.learning.datascope.infrastructure.persistence.OrganizationAdminMapper;
import com.lingdong.learning.auth.infrastructure.persistence.ParentAuthenticationMapper;
import com.lingdong.learning.common.id.IdGenerator;
import com.lingdong.learning.audit.infrastructure.persistence.SystemTaskMapper;
import org.junit.jupiter.api.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
/** Boundary preflight tests. Actual MySQL transaction rollback is a separate acceptance check. */
class OrganizationOnboardingApiIntegrationTest {
 OnboardingMapper mapper=mock(OnboardingMapper.class);UserMapper users=mock(UserMapper.class);OrganizationMapper organizations=mock(OrganizationMapper.class);
 UserOrganizationMapper memberships=mock(UserOrganizationMapper.class);UserRoleMapper grants=mock(UserRoleMapper.class);RoleMapper roles=mock(RoleMapper.class);OrganizationAdminMapper admins=mock(OrganizationAdminMapper.class);ParentAuthenticationMapper profiles=mock(ParentAuthenticationMapper.class);IdGenerator ids=mock(IdGenerator.class);SystemTaskMapper tasks=mock(SystemTaskMapper.class);
 OrganizationOnboardingService service;
 @BeforeEach void setup(){service=new OrganizationOnboardingService(mapper,users,organizations,memberships,grants,roles,admins,profiles,ids,tasks);org.springframework.test.util.ReflectionTestUtils.setField(service,"features",mock(com.lingdong.learning.feature.application.FeatureAccessService.class));}
 @Test void familyRequiresValidRegionBeforeAnyWrite(){when(users.findByIdForUpdate(1L)).thenReturn(User.create(1L,"parent","Parent",null,UserType.PERSONAL));assertThrows(IllegalArgumentException.class,()->service.family(1L,"家庭","request",null));when(organizations.findByIdForUpdate(50L)).thenReturn(com.lingdong.learning.organization.domain.Organization.create(50L,null,"SCHOOL:50","S50","学校","SCHOOL","/S50/",0,null));assertThrows(IllegalArgumentException.class,()->service.family(1L,"家庭","request",50L));verifyNoInteractions(mapper,memberships,grants,admins,ids);}
 @Test void studentCannotCreateOrQuery(){when(users.findByIdForUpdate(1L)).thenReturn(User.create(1L,"student","Student",null,UserType.STUDENT));assertThrows(IllegalArgumentException.class,()->service.family(1L,"家庭","request"));assertThrows(IllegalArgumentException.class,()->service.applications(1L));verifyNoInteractions(mapper,organizations,memberships,grants,admins);}
 @Test void otherApplicantCannotRead(){when(users.findByIdForUpdate(1L)).thenReturn(User.create(1L,"platform","Platform",null,UserType.PLATFORM));when(mapper.lock(3L)).thenReturn(java.util.Map.of("applicantId",2L));assertThrows(IllegalArgumentException.class,()->service.application(1L,3L));verifyNoInteractions(organizations,memberships,grants,admins);}
 @Test void inactiveAccountCannotCreate(){when(users.findByIdForUpdate(1L)).thenReturn(null);assertThrows(IllegalArgumentException.class,()->service.family(1L,"家庭","request"));verifyNoInteractions(mapper,organizations,memberships,grants,admins);}
 @Test void invalidInstitutionTypeCannotCreateTask(){when(users.findByIdForUpdate(1L)).thenReturn(User.create(1L,"parent","Parent","13800000000",UserType.FAMILY));assertThrows(IllegalArgumentException.class,()->service.submit(1L,new OrganizationOnboardingService.Form("CLASS","名字",2L,"联系人",null,null)));verifyNoInteractions(tasks,mapper,memberships,grants,admins);}
 @Test void familyRetryReturnsExistingOrganizationWithoutNewGrants(){when(users.findByIdForUpdate(1L)).thenReturn(User.create(1L,"platform","Platform",null,UserType.PLATFORM));when(mapper.family(1L,"request")).thenReturn(9L);when(organizations.findById(9L)).thenReturn(com.lingdong.learning.organization.domain.Organization.create(9L,null,"FAMILY:9","F9","家庭","FAMILY","/F9/",0,null));var result=service.family(1L,"家庭","request");assertEquals("9",result.id());verify(memberships,never()).insert(anyLong(),anyLong(),anyLong());verify(grants,never()).insert(anyLong(),anyLong(),anyLong(),anyLong(),anyString());verifyNoInteractions(ids);verify(organizations,never()).insert(any());}
 @Test void retryCannotReuseKeyForDifferentName(){when(users.findByIdForUpdate(1L)).thenReturn(User.create(1L,"platform","Platform",null,UserType.PLATFORM));when(mapper.family(1L,"request")).thenReturn(9L);when(organizations.findById(9L)).thenReturn(com.lingdong.learning.organization.domain.Organization.create(9L,null,"FAMILY:9","F9","家庭","FAMILY","/F9/",0,null));assertThrows(IllegalArgumentException.class,()->service.family(1L,"另一个家庭","request"));verify(memberships,never()).insert(anyLong(),anyLong(),anyLong());verify(grants,never()).insert(anyLong(),anyLong(),anyLong(),anyLong(),anyString());verifyNoInteractions(ids);}
 @Test void staleBatchCannotWithdrawOrCreateAnAuditEvent(){when(users.findByIdForUpdate(1L)).thenReturn(User.create(1L,"parent","Parent","13800000000",UserType.FAMILY));when(mapper.lock(3L)).thenReturn(java.util.Map.of("applicantId",1L,"status","PENDING","versionNo",3,"submissionBatch",2));assertThrows(IllegalStateException.class,()->service.withdraw(1L,3L,1,1));verify(mapper,never()).transition(any());verifyNoInteractions(tasks,organizations,memberships,grants,admins);}
 @Test void withdrawnBatchCannotApproveAnOrganization(){when(mapper.byTask(8L)).thenReturn(3L);when(mapper.lock(3L)).thenReturn(java.util.Map.of("applicantId",1L,"status","WITHDRAWN","versionNo",2,"submissionBatch",1,"taskId",8L));assertThrows(IllegalStateException.class,()->service.review(8L,2L,true,null));verifyNoInteractions(users,organizations,memberships,grants,admins,roles);}
 @Test void existingOrdinaryParentCanEnterItsFamilyWithoutAdministratorRole(){when(users.findByIdForUpdate(1L)).thenReturn(User.create(1L,"parent","Parent",null,UserType.FAMILY));when(memberships.findOrganizationIds(1L)).thenReturn(java.util.List.of(9L));when(memberships.exists(1L,9L)).thenReturn(true);when(organizations.findByIds(java.util.List.of(9L))).thenReturn(java.util.List.of(com.lingdong.learning.organization.domain.Organization.create(9L,null,"FAMILY:9","F9","家庭","FAMILY","/F9/",0,null)));when(profiles.findProfileByUserId(1L)).thenReturn(new com.lingdong.learning.auth.application.ParentProfile(20L,1L,com.lingdong.learning.auth.application.ParentOnboardingStatus.COMPLETED,null,null));when(grants.hasAnyEnabledRole(1L)).thenReturn(true);when(grants.hasRoleCode(1L,"PARENT")).thenReturn(true);var result=service.myOrganizations(1L).get(0);assertTrue(result.canEnterFamily());assertEquals(java.util.List.of("PARENT"),result.roleCodes());assertFalse(result.canEnterInstitution());assertFalse(result.owner());}
 @Test void closedOrganizationFeatureCannotCreateEvenForMobileCaller(){when(users.findByIdForUpdate(1L)).thenReturn(User.create(1L,"parent","Parent",null,UserType.FAMILY));when(mapper.family(1L,"request")).thenReturn(null);var features=mock(com.lingdong.learning.feature.application.FeatureAccessService.class);org.springframework.test.util.ReflectionTestUtils.setField(service,"features",features);doThrow(new IllegalStateException("closed")).when(features).requireEnabled("ORGANIZATION_MANAGEMENT",null);assertThrows(IllegalStateException.class,()->service.family(1L,"家庭","request"));verifyNoInteractions(organizations,memberships,grants,admins,roles);}
 @Test void platformFamilyCreationPreservesAccountTypeAndScopesNewRole(){var account=User.create(1L,"platform","Platform",null,UserType.PLATFORM);when(users.findByIdForUpdate(1L)).thenReturn(account);when(mapper.family(1L,"request")).thenReturn(null);when(ids.nextId()).thenReturn(9L,10L,11L,12L);when(roles.findByCode("PARENT_ADMIN")).thenReturn(com.lingdong.learning.iam.domain.Role.custom(30L,"PARENT_ADMIN","家长管理员",null,com.lingdong.learning.iam.domain.RoleDataScope.FAMILY));when(organizations.insert(any())).thenReturn(1);when(memberships.insert(anyLong(),anyLong(),anyLong())).thenReturn(1);when(grants.insert(anyLong(),anyLong(),anyLong(),anyLong(),anyString())).thenReturn(1);when(grants.markAutomaticOrganizationAdmin(anyLong(),anyLong(),anyLong())).thenReturn(1);when(admins.insert(anyLong(),anyLong(),anyLong())).thenReturn(1);when(mapper.owner(anyLong(),anyLong())).thenReturn(1);when(profiles.insertProfile(any())).thenReturn(1);when(organizations.findByIdForUpdate(50L)).thenReturn(com.lingdong.learning.organization.domain.Organization.create(50L,null,"REGION:50","R50","区域","REGION","/R50/",0,null));service.family(1L,"家庭","request",50L);var organizationCaptor=org.mockito.ArgumentCaptor.forClass(com.lingdong.learning.organization.domain.Organization.class);verify(organizations).insert(organizationCaptor.capture());assertEquals(50L,organizationCaptor.getValue().parentId());assertTrue(organizationCaptor.getValue().path().startsWith("/R50/"));verify(grants).insert(11L,1L,30L,9L,"ORG:9");verify(memberships).insert(10L,1L,9L);verify(admins).insert(12L,1L,9L);verify(mapper).owner(9L,1L);var profileCaptor=org.mockito.ArgumentCaptor.forClass(com.lingdong.learning.auth.application.ParentProfile.class);verify(profiles).insertProfile(profileCaptor.capture());assertEquals(com.lingdong.learning.auth.application.ParentOnboardingStatus.PENDING,profileCaptor.getValue().onboardingStatus());assertNull(profileCaptor.getValue().onboardingCompletedAt());assertEquals(UserType.PLATFORM,account.type());verify(users,times(2)).findByIdForUpdate(1L);verifyNoMoreInteractions(users);}
}









